### Timeout Enforcement Loop (lines 1567-1650):
The main timeout enforcement uses a select! loop with four branches:
1. **Child exit** - Monitor process completion
2. **Activity detection** - Reset idle deadline on stdout/stderr activity
3. **Idle deadline expiration** - Kill process group with `killpg(pid, SIGKILL)`
4. **Hard deadline expiration** - Kill process group with `killpg(pid, SIGKILL)`

```rust
let outcome: (i32, Option<TimeoutReason>) = loop {
    let next_idle = idle_deadline;
    let next_hard = hard_deadline;

    select! {
        status = guard.wait_borrowed() => {
            // Child exited naturally
            break (status.code().unwrap_or(-1), None);
        }

        _result = activity_rcv.changed() => {
            // Reset idle deadline on activity
            if has_idle_deadline {
                idle_deadline = Some(tokio::time::Instant::now() + idle_dur);
            }
            continue;
        }

        () = async { /* idle deadline expired */ }, if has_idle_deadline => {
            unsafe { libc::killpg(pid as libc::pid_t, libc::SIGKILL); }
            break (124, Some(TimeoutReason::Idle { ... }));
        }

        () = async { /* hard deadline expired */ }, if has_hard_deadline => {
            unsafe { libc::killpg(pid as libc::pid_t, libc::SIGKILL); }
            break (124, Some(TimeoutReason::Hard { ... }));
        }
    }
};
```

